// "TAKEN" means the field already exists, which is fine on a second run.
const d = $input.first().json.data || {};
const out = [], bad = [];
for (const [field, r] of Object.entries(d)) {
  const errs = (r && r.userErrors) || [];
  if (r && r.createdDefinition) out.push(field + ': created');
  else if (errs.length && errs.every(e => e.code === 'TAKEN')) out.push(field + ': already there');
  else bad.push(field + ': ' + JSON.stringify(errs));
}
if ($input.first().json.errors) bad.push(JSON.stringify($input.first().json.errors));
if (bad.length) throw new Error('Shopify refused some fields: ' + bad.join('; '));
return [{ json: { fields: out } }];

