parameters.jsCode:
const s = $('Link settings').first().json;
const pages = $('Read collections').all();
for (const p of [...pages, ...$('Read products').all()]) if (p.json.errors) throw new Error(JSON.stringify(p.json.errors).slice(0, 500));
const cols = pages.flatMap(i => i.json.data.collections.nodes).filter(c => !s.skip_handles.includes(c.handle));
const menus = pages[0].json.data.menus.nodes;
const products = $('Read products').all().flatMap(i => i.json.data.products.nodes);
const byHandle = Object.fromEntries(cols.map(c => [c.handle, c]));
const byId = Object.fromEntries(cols.map(c => [c.id, c]));
const rules = c => (c && c.ruleSet && c.ruleSet.rules) || [];
const size = h => (byHandle[h] && byHandle[h].productsCount.count) || 0;

// 1. The tree comes from how the tree menu is nested, in menu order...
const parent = {}, kids = {}, rank = {};
const seen = h => { if (!(h in rank)) rank[h] = Object.keys(rank).length; };
const isUnder = (up, h) => { for (let x = up, n = 0; x && n < 20; x = parent[x], n++) if (x === h) return true; return false; };
const adopt = (h, up) => {
  if (!h || !up || h === up || !byHandle[h] || !byHandle[up] || parent[h] || isUnder(up, h)) return;
  parent[h] = up;
  (kids[up] = kids[up] || []).push(h);
  seen(h);
};
const handleOf = it => (byId[it.resourceId] || {}).handle || ((it.url || '').match(/\/collections\/([^/?#]+)/) || [])[1];
const walk = (items, up) => {
  for (const it of items || []) {
    const h = byHandle[handleOf(it)] ? handleOf(it) : null;
    if (h) seen(h);
    adopt(h, up);
    walk(it.items, h || up);
  }
};
const tree = menus.find(m => m.handle === s.tree_menu);
if (!tree) throw new Error('No menu with the handle "' + s.tree_menu + '". Check tree_menu in Link settings.');
walk(tree.items, null);
if (!Object.keys(rank).length) throw new Error('The menu "' + s.tree_menu + '" links to no published collection, so nothing would have a parent.');

// ...then from rules, for collections outside the menu:
// "type is X and ..." sits under the collection whose only rule is "type is X".
const typePage = {};
for (const c of cols) {
  const r = rules(c);
  if (r.length === 1 && r[0].column === 'TYPE' && r[0].relation === 'EQUALS') typePage[r[0].condition.toLowerCase()] ??= c.handle;
}
for (const c of [...cols].sort((a, b) => a.title.localeCompare(b.title))) {
  if (!c.ruleSet || c.ruleSet.appliedDisjunctively || rules(c).length < 2) continue;
  const t = rules(c).find(r => r.column === 'TYPE' && r.relation === 'EQUALS');
  if (t) adopt(c.handle, typePage[t.condition.toLowerCase()]);
}

// Spec pages: a collection whose rules are one product metafield (or standard product attribute)
// condition, plus at most "type is X", is the page for that spec value: "Resolution is 4MP" links to it.
const specKey = c => {
  if (!c.ruleSet || c.ruleSet.appliedDisjunctively) return null;
  const r = rules(c), m = r.filter(x => x.column === 'PRODUCT_METAFIELD_DEFINITION' && x.relation === 'EQUALS');
  const def = m.length === 1 && m[0].conditionObject && m[0].conditionObject.metafieldDefinition;
  if (!def || r.some(x => x !== m[0] && !(x.column === 'TYPE' && x.relation === 'EQUALS')) || r.length > 2) return null;
  return def.namespace + '.' + def.key;
};
const specOf = Object.fromEntries(cols.map(c => [c.handle, specKey(c)]).filter(([, k]) => k));

// Brand pages: the collection whose only rule is "vendor is X" (Shopify matches vendors without case).
const brandOf = {};
for (const c of cols) {
  const r = rules(c);
  if (r.length === 1 && r[0].column === 'VENDOR' && r[0].relation === 'EQUALS') brandOf[r[0].condition.toLowerCase()] ??= c.handle;
}
const brandPages = new Set(Object.values(brandOf));
const inTree = h => h in rank;
const depth = h => { let d = 0; for (let x = h; parent[x] && d < 20; x = parent[x]) d++; return d; };
const path = h => { const out = []; for (let x = h; x && out.length < 20; x = parent[x]) out.push(x); return out; };

// 2. Compare with what the store has now and keep only the changes.
const today = new Date().toISOString().slice(0, 10);
const names = v => { if (!v) return ''; let ids = [v]; if (v.startsWith('[')) { try { ids = JSON.parse(v); } catch (e) {} } return ids.map(id => (byId[id] || {}).handle || id).join(', '); };
const changes = [];
const compare = (owner, ownerId, handle, field, type, have, want, show = names) => {
  have = have || '';
  if (want === have) return;
  changes.push({ json: { run_date: today, owner, owner_id: ownerId, handle, field, type, value: want,
    old_value: show(have), new_value: show(want) } });
};
// Spec links are JSON, so compare them with sorted keys and show them as "key: handle".
const sortedJson = o => JSON.stringify(Object.fromEntries(Object.entries(o).sort(([a], [b]) => a.localeCompare(b))));
const specJson = v => { if (!v) return ''; try { return sortedJson(JSON.parse(v)); } catch (e) { return v; } };
const specShow = v => { if (!v) return ''; try { return Object.entries(JSON.parse(v)).map(([k, h]) => k.split('.').pop() + ': ' + h).join(', '); } catch (e) { return v; } };
const one = h => (h ? byHandle[h].id : '');
const list = hs => (hs.length ? JSON.stringify(hs.map(h => byHandle[h].id)) : '');

if (s.write_collection_links) for (const c of cols) {
  compare('collection', c.id, c.handle, 'parent_collection', 'collection_reference', c.parent && c.parent.value, one(parent[c.handle]));
  const children = (kids[c.handle] || []).filter(h => size(h) >= s.min_products).slice(0, s.max_children);
  compare('collection', c.id, c.handle, 'sub_collections', 'list.collection_reference', c.subs && c.subs.value, list(children));
}
for (const p of products) {
  const mine = p.collections.nodes.map(n => (byId[n.id] || {}).handle).filter(Boolean);
  // Primary: the deepest tree collection the product is in. Collections with a vendor rule are skipped:
  // a breadcrumb says what the product is, the brand link says who makes it. Ties go to menu order.
  const primary = mine.filter(h => inTree(h) && !rules(byHandle[h]).some(r => r.column === 'VENDOR'))
    .sort((a, b) => depth(b) - depth(a) || rank[a] - rank[b])[0] || '';
  const onPath = new Set(primary ? path(primary) : []);
  // Spec links: for each spec, the spec page the product is in, even when the breadcrumb runs through it.
  // One with a type rule beats one without, then the smallest. A page holding only this product adds nothing.
  const specs = {};
  for (const h of mine.filter(h => specOf[h] && size(h) >= Math.max(2, s.min_products))
    .sort((a, b) => rules(byHandle[b]).length - rules(byHandle[a]).length || size(a) - size(b) || a.localeCompare(b))) specs[specOf[h]] ??= h;
  // Related: every other collection it's in, smallest (most specific) first. A collection holding only
  // this product adds nothing. Spec collections stay in, by name, alongside the spec value links.
  const related = mine.filter(h => !onPath.has(h) && !brandPages.has(h) && size(h) >= Math.max(2, s.min_products))
    .sort((a, b) => size(a) - size(b) || a.localeCompare(b)).slice(0, s.max_related);
  const brand = brandOf[String(p.vendor || '').toLowerCase()] || '';
  if (s.write_brand) compare('product', p.id, p.handle, 'brand', 'collection_reference', p.brand && p.brand.value, one(brand));
  if (s.write_primary) compare('product', p.id, p.handle, 'primary_collection', 'collection_reference', p.primary && p.primary.value, one(primary));
  if (s.write_spec_links) compare('product', p.id, p.handle, 'spec_links', 'json', specJson(p.specs && p.specs.value),
    Object.keys(specs).length ? sortedJson(specs) : '', specShow);
  if (s.write_related) compare('product', p.id, p.handle, 'related_collections', 'list.collection_reference', p.related && p.related.value, list(related));
}
return changes;

