  const s = $('Link settings').first().json;
  const ch = $('Plan the links').all().map(i => i.json);
  const labels = { parent_collection: 'Breadcrumb parents', sub_collections: 'Sub-collection lists',
    brand: 'Brand links', primary_collection: 'Product breadcrumbs', spec_links: 'Spec links', related_collections: 'Shop more like this' };
