    return '*' + label + '* (' + xs.length + ')\n  ' + shown + (xs.length > 8 ? '\n  ...' : '') + '\n';
  }).join('');
  return { channel: s.slack_channel, unfurl_links: false,
    text: (s.dry_run ? ':memo: Link plan (dry run, nothing written): ' : ':link: Links updated: ') + ch.length + (ch.length === 1 ? ' change' : ' changes') + '\n' + lines };
})()) }}

