// metafieldsSet takes up to 25 fields a call; an empty field is deleted rather than set.
const s = $('Link settings').first().json;
const all = $input.all().map(i => i.json);
const chunk = (xs, n) => Array.from({ length: Math.ceil(xs.length / n) }, (_, i) => xs.slice(i * n, i * n + n));
const sets = all.filter(c => c.value)
  .map(c => ({ ownerId: c.owner_id, namespace: s.namespace, key: c.field, type: c.type, value: c.value }));
const dels = all.filter(c => !c.value).map(c => ({ ownerId: c.owner_id, namespace: s.namespace, key: c.field }));
const SET = `mutation Set($m: [MetafieldsSetInput!]!) {
  metafieldsSet(metafields: $m) { metafields { id } userErrors { field message code } } }`;
const DEL = `mutation Del($m: [MetafieldIdentifierInput!]!) {
  metafieldsDelete(metafields: $m) { deletedMetafields { key } userErrors { field message } } }`;
return [
  ...chunk(sets, 25).map(m => ({ json: { query: SET, variables: { m } } })),
  ...chunk(dels, 25).map(m => ({ json: { query: DEL, variables: { m } } })),
];

// Shopify answers refused writes with HTTP 200 and userErrors, so check them here.
const errs = $input.all().flatMap(i => [
  ...((i.json.data && i.json.data.metafieldsSet && i.json.data.metafieldsSet.userErrors) || []),
  ...((i.json.data && i.json.data.metafieldsDelete && i.json.data.metafieldsDelete.userErrors) || []),
  ...(i.json.errors || []),
]);
if (errs.length) throw new Error('Shopify refused some links: ' + JSON.stringify(errs).slice(0, 500));
return [{ json: { batches: $input.all().length } }];

