parameters.jsCode:
const s = $('Audit settings').first().json;
const pages = $('Audit read collections').all();
const content = $('Read pages, posts and redirects').first().json;
for (const p of [...pages, ...$('Audit read products').all(), $input.first()]) if (p.json.errors) throw new Error(JSON.stringify(p.json.errors).slice(0, 500));
if (content.errors) throw new Error(JSON.stringify(content.errors).slice(0, 500));
const cols = pages.flatMap(i => i.json.data.collections.nodes).filter(c => !s.ignore.includes(c.handle));
const menus = pages[0].json.data.menus.nodes.filter(m => !s.skip_menus.includes(m.handle));
const docs = [...content.data.pages.nodes.map(d => ({ handle: 'pages/' + d.handle, body: d.body })),
  ...content.data.articles.nodes.map(d => ({ handle: 'blogs/' + d.blog.handle + '/' + d.handle, body: d.body }))];
const redirects = Object.fromEntries(content.data.urlRedirects.nodes.map(r => [r.path.toLowerCase(), r.target]));
const products = $('Audit read products').all().flatMap(i => i.json.data.products.nodes);

const byHandle = Object.fromEntries(cols.map(c => [c.handle, c]));
const byId = Object.fromEntries(cols.map(c => [c.id, c]));
const h = id => (byId[id] || {}).handle;
const size = c => (c && c.productsCount.count) || 0;
const rules = c => (c && c.ruleSet && c.ruleSet.rules) || [];
const list = v => { try { return JSON.parse(v || '[]'); } catch (e) { return []; } };
const hrefs = (html, type) => [...String(html || '').matchAll(new RegExp('href="[^"]*/' + type + '/([a-z0-9-]+)', 'gi'))]
  .map(m => m[1].toLowerCase());
const ancestors = start => { const out = []; for (let x = start; x && out.length < 20; x = h((byHandle[x].parent || {}).value)) out.push(x); return out; };

// Every link the audit can see, as target -> set of "surface:source".
const inbound = {};
const add = (target, surface, source) => {
  if (target && byHandle[target] && target !== source) (inbound[target] = inbound[target] || new Set()).add(surface + ':' + source);
};
const inMenu = new Set();
const walk = items => { for (const it of items || []) {
  const t = h(it.resourceId) || ((it.url || '').match(/\/collections\/([^/?#]+)/) || [])[1];
  if (t) inMenu.add(t);
  walk(it.items);
} };
menus.forEach(m => walk(m.items));
const shown = c => list(c && c.subs && c.subs.value).slice(0, s.max_pills).map(h).filter(x => x && size(byHandle[x]) > 0); // the theme hides empty ones
for (const c of cols) {
  shown(c).forEach(x => add(x, 'sub-collection link', c.handle));
  const up = h((c.parent || {}).value);
  if (up) {
    ancestors(up).forEach(x => add(x, 'breadcrumb', c.handle));
    if (!shown(c).length) shown(byHandle[up]).forEach(x => add(x, 'sibling link', c.handle)); // no children: siblings instead
  }
  hrefs(c.descriptionHtml, 'collections').forEach(x => add(x, 'description', c.handle));
}
docs.forEach(d => hrefs(d.body, 'collections').forEach(x => add(x, 'page or post', d.handle)));
for (const p of products) {
  add(h((p.brand || {}).value), 'brand link', p.handle);
  const primary = h((p.primary || {}).value);
  if (primary) ancestors(primary).forEach(x => add(x, 'product breadcrumb', p.handle));
  list((p.related || {}).value).map(h).forEach(x => add(x, 'shop more like this', p.handle));
  let specs = {}; try { specs = JSON.parse((p.specs || {}).value || '{}'); } catch (e) {}
  Object.values(specs).forEach(x => add(x, 'spec link', p.handle));
}

const today = new Date().toISOString().slice(0, 10);
const out = [];
const find = (kind, handle, issue, detail = '', links = 0) =>
  out.push({ json: { run_date: today, kind, handle, issue, detail, inbound: links } });

for (const c of cols) {
  const links = inbound[c.handle] ? [...inbound[c.handle]] : [];
  const reached = inMenu.has(c.handle) || s.theme_linked.includes(c.handle);
  if (inMenu.has(c.handle) && size(c) === 0) find('collection', c.handle, 'menu links to an empty collection');
  else if (!reached && size(c) > 0 && links.length === 0) find('collection', c.handle, 'orphan');
  else if (!reached && size(c) > 0 && links.length < s.weak_below) find('collection', c.handle, 'weak', links.join(', '), links.length);
  const up = byHandle[h((c.parent || {}).value)];
  if (up && size(c) > 0 && !shown(up).includes(c.handle) && !hrefs(up.descriptionHtml, 'collections').includes(c.handle))
    find('collection', c.handle, 'not linked from its parent', up.handle, links.length);
}

// Links that go through a redirect or lead nowhere.
const live = new Set(products.map(p => p.handle));
for (const [source, html] of [...cols.map(c => [c.handle, c.descriptionHtml]), ...docs.map(d => [d.handle, d.body])]) {
  for (const type of ['collections', 'products']) for (const x of hrefs(html, type)) {
    const to = redirects['/' + type + '/' + x];
    if (to) find('link', source, 'link through a redirect', '/' + type + '/' + x + ' > ' + to);
    else if (type === 'collections' ? !byHandle[x] && !s.ignore.includes(x) : !live.has(x)) find('link', source, 'broken link', '/' + type + '/' + x);
  }
}

// Products and vendors.
const brandVendors = new Set(cols.filter(c => rules(c).length === 1 && rules(c)[0].column === 'VENDOR').map(c => rules(c)[0].condition.toLowerCase()));
const noBrand = {};
for (const p of products) {
  const mine = p.collections.nodes.map(n => h(n.id)).filter(Boolean);
  if (!mine.length) find('product', p.handle, 'in no published collection');
  else if (s.check_product_fields && !(p.primary || {}).value) find('product', p.handle, 'no primary collection');
  if (p.vendor && !brandVendors.has(p.vendor.toLowerCase())) noBrand[p.vendor] = (noBrand[p.vendor] || 0) + 1;
}
for (const [v, n] of Object.entries(noBrand)) find('vendor', v, 'no brand page', n + (n === 1 ? ' product' : ' products'));

// Optional: theme settings that hide links (check_theme, read_themes scope).
const theme = (($input.first().json.data || {}).themes || { nodes: [] }).nodes[0];
if (s.check_theme && theme) {
  const file = n => { const f = theme.files.nodes.find(x => x.filename === n); return f && f.body ? f.body.content : ''; };
  const col = file('templates/collection.json'), prod = file('templates/product.json');
  // Horizon's "Auto load products on scroll" is on unless the template saves it as false.
  if (!/"enable_infinite_scroll"\s*:\s*false/.test(col)) find('theme', 'templates/collection.json', 'products load on scroll, so page 2 has no link');
  if (!/parent_collection/.test(col)) find('theme', 'templates/collection.json', 'no breadcrumb block');
  if (!/sub_collections/.test(col)) find('theme', 'templates/collection.json', 'no sub-collection links block');
  if (!/primary_collection/.test(prod)) find('theme', 'templates/product.json', 'no product breadcrumb block');
  if (!/custom\.brand|\.brand\.value/.test(prod)) find('theme', 'templates/product.json', 'no brand link block');
  if (products.some(p => (p.specs || {}).value) && !/spec_links/.test(prod)) find('theme', 'templates/product.json', 'no linked specs table');
}
return out;

