  const by = k => f.filter(x => x.issue === k);
  const line = (label, xs, fmt) => xs.length ? '*' + label + '* (' + xs.length + '): '
    + xs.slice(0, 15).map(fmt).join(', ') + (xs.length > 15 ? ', ...' : '') + '\n' : '';
  return { channel: $('Audit settings').first().json.slack_channel, unfurl_links: false,
    text: ':mag: Weekly internal link audit\n' +
      (f.length ? '' : 'No orphans, weak pages or broken links this week.\n') +
      line('Orphans, nothing links to them', by('orphan'), x => x.handle) +
      line('Weak, only one link in', by('weak'), x => x.handle + ' (' + x.detail + ')') +
      line('Not linked from their parent', by('not linked from its parent'), x => x.handle + ' (parent ' + x.detail + ')') +
      line('Menu links to empty collections', by('menu links to an empty collection'), x => x.handle) +
      line('Broken links', by('broken link'), x => x.handle + ' > ' + x.detail) +
      line('Links through a redirect', by('link through a redirect'), x => x.handle + ': ' + x.detail) +
      line('Products in no published collection', by('in no published collection'), x => x.handle) +
      line('Products with no primary collection', by('no primary collection'), x => x.handle) +
      line('Vendors with no brand page', by('no brand page'), x => x.handle + ' (' + x.detail + ')') +
      line('Theme', f.filter(x => x.kind === 'theme'), x => x.handle.replace('templates/', '') + ': ' + x.issue) };
})()) }}
